package ratelimit

import (
	"errors"
	"sync"
	"time"
)

// Clock abstracts time for testability.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// RealClock returns a Clock backed by the wall clock.
func RealClock() Clock { return realClock{} }

// Limiter is a concurrency-safe token-bucket rate limiter.
// A zero-value Limiter is not usable; use New.
type Limiter struct {
	mu       sync.Mutex
	rate     float64   // tokens per second
	burst    float64   // bucket capacity
	tokens   float64   // available tokens
	last     time.Time // last refill time
	clock    Clock
}

var (
	ErrNonPositiveRate  = errors.New("ratelimit: rate must be > 0")
	ErrNonPositiveBurst = errors.New("ratelimit: burst must be > 0")
	ErrNilClock         = errors.New("ratelimit: clock must not be nil")
)

// New creates a Limiter that refills at rate tokens per second up to burst.
func New(rate float64, burst int, clock Clock) (*Limiter, error) {
	if rate <= 0 {
		return nil, ErrNonPositiveRate
	}
	if burst <= 0 {
		return nil, ErrNonPositiveBurst
	}
	if clock == nil {
		return nil, ErrNilClock
	}
	now := clock.Now()
	return &Limiter{
		rate:   rate,
		burst:  float64(burst),
		tokens: float64(burst), // start full
		last:   now,
		clock:  clock,
	}, nil
}

// advance refills tokens based on elapsed time. Caller must hold l.mu.
func (l *Limiter) advance(now time.Time) {
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
}

// AllowN reports whether n tokens may be consumed at time now.
// If allowed, the tokens are consumed.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Allow reports whether one token may be consumed now.
func (l *Limiter) Allow() bool {
	return l.AllowN(l.clock.Now(), 1)
}

// RetryAfter returns the duration until n tokens would be available,
// or 0 if they are available now. It does not consume tokens.
func (l *Limiter) RetryAfter(now time.Time, n int) time.Duration {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(now)
	need := float64(n) - l.tokens
	if need <= 0 {
		return 0
	}
	return time.Duration(need / l.rate * float64(time.Second))
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
}
