type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// Tokens refill continuously at rate tokens per second, up to burst capacity.
// The zero value is not usable; construct with NewLimiter.
type Limiter struct {
	mu        sync.Mutex
	tokens    float64
	last      time.Time
	rate      float64 // tokens per second
	burst     float64 // capacity
	clock     Clock
	nowFnName string // for error messages only
}

// NewLimiter creates a Limiter that admits events at rate tokens per second
// with a maximum burst of burst tokens. The bucket starts full.
// rate must be > 0 and burst must be >= 1.
func NewLimiter(rate float64, burst int) (*Limiter, error) {
	return NewLimiterWithClock(rate, burst, realClock{})
}

// NewLimiterWithClock is NewLimiter with an injectable Clock, for testing.
func NewLimiterWithClock(rate float64, burst int, clock Clock) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: clock must not be nil")
	}
	if rate <= 0 {
		return nil, fmt.Errorf("ratelimit: rate must be > 0, got %v", rate)
	}
	if burst < 1 {
		return nil, fmt.Errorf("ratelimit: burst must be >= 1, got %d", burst)
	}
	now := clock.Now()
	return &Limiter{
		tokens: float64(burst),
		last:   now,
		rate:   rate,
		burst:  float64(burst),
		clock:  clock,
	}, nil
}

// advance refills tokens based on elapsed time since last. Caller holds mu.
func (l *Limiter) advance(now time.Time) {
	if now.After(l.last) {
		elapsed := now.Sub(l.last).Seconds()
		l.tokens = min(l.burst, l.tokens+elapsed*l.rate)
		l.last = now
	}
}

// Allow reports whether a single token is available.
func (l *Limiter) Allow() bool { return l.AllowN(1) }

// AllowN reports whether n tokens are available at the current time,
// consuming them if so. n must be >= 1; AllowN returns false for n <= 0.
func (l *Limiter) AllowN(n int) bool {
	if n <= 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(l.clock.Now())
	need := float64(n)
	if l.tokens >= need {
		l.tokens -= need
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for tests/monitoring).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	l.advance(l.clock.Now())
	return l.tokens
}

func min(a, b float64) float64 {
	if a < b {
		return a
	}
	return b
