```ratelimit.go
// Package ratelimit implements a concurrency-safe token-bucket rate limiter.
package ratelimit

import (
	"errors"
	"fmt"
	"sync"
	"time"
)

// Clock reports the current time. It is injectable for testing.
type Clock interface {
	Now() time.Time
}

type realClock struct{}

func (realClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
// The zero value is not usable; construct with New.
type Limiter struct {
	mu     sync.Mutex
	tokens float64
	last   time.Time
	limit  float64 // tokens added per second
	burst  float64 // bucket capacity
	clock  Clock
}

// ErrInvalidConfig is returned by New when limit or burst are not positive.
var ErrInvalidConfig = errors.New("ratelimit: limit and burst must be > 0")

// New returns a Limiter that admits events at rate limit events per second,
// with a maximum burst size of burst tokens. The bucket starts full.
func New(limit float64, burst int, clock Clock) (*Limiter, error) {
	if limit <= 0 || burst <= 0 {
		return nil, fmt.Errorf("%w: got limit=%v burst=%d", ErrInvalidConfig, limit, burst)
	}
	if clock == nil {
		clock = realClock{}
	}
	return &Limiter{
		tokens: float64(burst),
		limit:  limit,
		burst:  float64(burst),
		clock:  clock,
	}, nil
}

// Allow reports whether one event may happen now.
func (l *Limiter) Allow() bool { return l.AllowN(time.Time{}, 1) }

// AllowN reports whether n events may happen now, refilling the bucket
// based on the current clock time. If now is the zero time, the clock is used.
// AllowN is safe for concurrent use.
func (l *Limiter) AllowN(now time.Time, n int) bool {
	if n < 0 {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	if now.IsZero() {
		now = l.clock.Now()
	}

	elapsed := now.Sub(l.last).Seconds()
	if elapsed > 0 {
		l.tokens += elapsed * l.limit
		if l.tokens > l.burst {
			l.tokens = l.burst
		}
		l.last = now
	}
	if l.last.IsZero() {
		l.last = now
	}

	if float64(n) <= l.tokens {
		l.tokens -= float64(n)
		return true
	}
	return false
}

// Tokens returns the current number of available tokens (for observability).
func (l *Limiter) Tokens() float64 {
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.tokens
}
